436	    pub fn remove(&mut self, window: WindowId) -> Result<(), LayoutError> {
437	        let index = self
438	            .column_index(window)
439	            .ok_or(LayoutError::UnknownWindow)?;
440	        let anchor = if self.mode == LayoutMode::Strip && self.focus != Some(window) {
441	            self.focus.map(|w| {
442	                (
443	                    w,
444	                    self.strip_placements()
445	                        .into_iter()
446	                        .find(|p| p.window == w)
447	                        .unwrap()
448	                        .rect
449	                        .x,
450	                )
451	            })
452	        } else {
453	            None
454	        };
455	        let c = &mut self.columns[index];
456	        c.windows.retain(|w| *w != window);
457	        if c.windows.is_empty() {
458	            self.canvas.remove(&c.group);
459	            self.columns.remove(index);
460	        } else if c.active == window {
461	            c.active = c
462	                .windows
463	                .iter()
464	                .copied()
465	                .find(|w| !self.minimized.contains(w))
466	                .unwrap_or(c.windows[0]);
467	        }
468	        self.members.remove(&window);
469	        self.minimized.remove(&window);
470	        self.history.retain(|w| *w != window);
471	        if self.focus == Some(window) {
472	            self.focus = None;
473	            if let Some(next) = self.replacement_focus(index) {
474	                self.focus_window(next)?;
475	            }
476	        }
477	        if let Some((w, old_x)) = anchor {
478	            let new_x = self
479	                .strip_placements()
480	                .into_iter()
481	                .find(|p| p.window == w)
482	                .unwrap()
483	                .rect
484	                .x;
485	            self.strip_camera.position.x =
486	                (self.strip_camera.position.x + new_x - old_x).clamp(-MAX_COORD, MAX_COORD);
487	            self.reveal_focus();
488	        }
489	        if self.is_empty() {
490	            self.strip_camera = Camera::default();
491	            self.canvas_camera = Camera::default();
492	        }
493	        Ok(())
494	    }
495	    /// Minimized members reserve their geometry and group slot. A real restore
496	    /// activates and reveals the member; repeated requests leave focus unchanged.
497	    pub fn set_minimized(&mut self, window: WindowId, minimized: bool) -> Result<(), LayoutError> {
498	        let index = self
499	            .column_index(window)
500	            .ok_or(LayoutError::UnknownWindow)?;
501	        if self.is_minimized(window) == minimized {
502	            return Ok(());
503	        }
504	        if !minimized {
505	            self.minimized.remove(&window);
506	            return self.focus_window(window);
507	        }
508	        self.minimized.insert(window);
509	        self.history.retain(|w| *w != window);
510	        if self.columns[index].active == window {
511	            let c = &mut self.columns[index];
512	            c.active = c
513	                .windows
514	                .iter()
515	                .copied()
516	                .find(|w| !self.minimized.contains(w))
517	                .unwrap_or(window);
518	        }
519	        if self.focus == Some(window) {
520	            self.focus = None;
521	            if let Some(next) = self.replacement_focus(index) {
522	                self.focus_window(next)?;
523	            }
524	        }
525	        Ok(())
526	    }
527	    /// Unknown and removed identities are never minimized.
528	    pub fn is_minimized(&self, window: WindowId) -> bool {
529	        self.minimized.contains(&window)
530	    }
531	    fn replacement_focus(&self, column: usize) -> Option<WindowId> {
532	        self.history
533	            .iter()
534	            .rev()
535	            .copied()
536	            .find(|w| !self.is_minimized(*w))
537	            .or_else(|| {
538	                self.columns
539	                    .iter()
540	                    .skip(column)
541	                    .chain(self.columns.iter().take(column))
542	                    .find_map(|c| (!self.is_minimized(c.active)).then_some(c.active))
543	            })
544	    }
545	    pub fn focus_window(&mut self, window: WindowId) -> Result<(), LayoutError> {
546	        let index = self
547	            .column_index(window)
548	            .ok_or(LayoutError::UnknownWindow)?;
549	        if self.is_minimized(window) {
550	            return Err(LayoutError::MinimizedWindow);
551	        }
552	        self.columns[index].active = window;
553	        self.focus = Some(window);
554	        self.history.retain(|w| *w != window);
555	        self.history.push(window);
556	        self.reveal_focus();
557	        Ok(())
558	    }
559	    pub fn set_constraints(
560	        &mut self,
561	        window: WindowId,
562	        constraints: SizeConstraints,
563	    ) -> Result<(), LayoutError> {
564	        if !constraints.valid() {
565	            return Err(LayoutError::InvalidConstraints);
566	        }
567	        if !self.members.contains_key(&window) {
568	            return Err(LayoutError::UnknownWindow);
569	        }
570	        self.check_strip_extent(
571	            self.viewport.width,
572	            self.gap,
573	            Some((window, constraints)),
574	            None,
575	            0.0,
576	        )?;
577	        let value = self.members.get_mut(&window).unwrap();
578	        *value = constraints;
579	        let group = self.columns[self.column_index(window).unwrap()].group;
580	        let minimum = self
581	            .columns
582	            .iter()
583	            .find(|c| c.group == group)
584	            .unwrap()
585	            .windows
586	            .iter()
587	            .map(|w| self.members[w].min.width)
588	            .fold(1.0, f64::max);
589	        self.canvas.get_mut(&group).unwrap().rect.width =
590	            self.canvas[&group].rect.width.max(minimum);
591	        self.reveal_focus();
592	        Ok(())
593	    }
594	    /// First conversion seeds from current strip geometry. First return sorts groups
595	    /// by x, y, stable identity; subsequent transitions restore saved cameras/geometry.
596	    pub fn set_mode(&mut self, mode: LayoutMode) {
597	        if self.mode == mode {
598	            return;
599	        }
600	        let mut reveal = false;
601	        if mode == LayoutMode::Canvas && !self.canvas_initialized {
602	            let mut x = 0.0;
603	            for c in &self.columns {
604	                let width = c
605	                    .windows
606	                    .iter()
607	                    .map(|w| self.members[w].min.width)
608	                    .fold(c.width.resolve(self.viewport.width).unwrap(), f64::max);
609	                self.canvas.insert(
610	                    c.group,
611	                    CanvasGroup {
612	                        rect: Rect {
613	                            x,
614	                            y: 0.0,
615	                            width,
616	                            height: self.viewport.height,
617	                        },
618	                        scroll_y: c.scroll_y,
619	                    },
620	                );
621	                x += width + self.gap;
622	            }
623	            self.canvas_initialized = true;
624	            reveal = true;
625	        } else if mode == LayoutMode::Strip && !self.strip_converted {
626	            self.columns.sort_by(|a, b| {
627	                let a_rect = self.canvas[&a.group].rect;
628	                let b_rect = self.canvas[&b.group].rect;
629	                a_rect
630	                    .x
631	                    .total_cmp(&b_rect.x)
632	                    .then(a_rect.y.total_cmp(&b_rect.y))
633	                    .then(a.group.cmp(&b.group))
634	            });
635	            self.strip_converted = true;
636	            reveal = true;
637	        }
638	        self.mode = mode;
639	        if reveal {
640	            self.reveal_focus();
641	        }
642	    }
643	    pub fn group_for(&self, window: WindowId) -> Option<GroupId> {
644	        self.column_index(window).map(|i| self.columns[i].group)
645	    }
646	    /// Groups with a selectable member. Fully minimized groups retain their
647	    /// stored geometry but have no active member to expose to interaction code.
648	    pub fn canvas_groups(&self) -> Vec<GroupGeometry> {
649	        self.columns
650	            .iter()
651	            .filter(|c| !self.is_minimized(c.active))
652	            .map(|c| GroupGeometry {
653	                id: c.group,
654	                rect: self.canvas[&c.group].rect,
655	                active: c.active,
656	                mode: c.mode,
657	            })
658	            .collect()
659	    }
660	    /// Resize/move the containing canvas group. Client minima are retained by its
661	    /// local layout; a member maximum constrains the member rather than its group.
662	    pub fn set_canvas_rect(&mut self, window: WindowId, rect: Rect) -> Result<(), LayoutError> {
663	        let group = self.group_for(window).ok_or(LayoutError::UnknownWindow)?;
664	        self.set_canvas_group_rect(group, rect)
665	    }
666	    pub fn set_canvas_group_rect(
667	        &mut self,
668	        group: GroupId,
669	        mut rect: Rect,
670	    ) -> Result<(), LayoutError> {
671	        if !valid_rect(rect) {
672	            return Err(LayoutError::InvalidGeometry);
673	        }
674	        let column = self
675	            .columns
676	            .iter()
677	            .find(|c| c.group == group)
678	            .ok_or(LayoutError::UnknownGroup)?;
679	        rect.width = column
680	            .windows
681	            .iter()
682	            .map(|w| self.members[w].min.width)
683	            .fold(rect.width, f64::max);
684	        self.canvas.get_mut(&group).unwrap().rect = rect;
685	        Ok(())
686	    }
687	    /// Explicit tab navigation; hidden tabs are excluded from spatial focus.
688	    pub fn cycle_tab(&mut self, forward: bool) -> Result<Option<WindowId>, LayoutError> {
689	        let Some(window) = self.focus else {
690	            return Ok(None);
691	        };
692	        let c = &self.columns[self.column_index(window).unwrap()];
693	        let windows: Vec<_> = c
694	            .windows
695	            .iter()
696	            .copied()
697	            .filter(|w| !self.is_minimized(*w))
698	            .collect();
699	        let index = windows.iter().position(|w| *w == window).unwrap();
700	        let next = windows[if forward {
701	            (index + 1) % windows.len()
702	        } else {
703	            (index + windows.len() - 1) % windows.len()
704	        }];
705	        self.focus_window(next)?;
706	        Ok(Some(next))
707	    }
708	    pub fn pan(&mut self, dx: f64, dy: f64) -> Result<(), LayoutError> {
709	        let old = self.camera();
710	        self.set_camera(Camera {
711	            position: Point {
712	                x: old.position.x + dx,
713	                y: old.position.y + dy,
714	            },
715	            ..old
716	        })
717	    }
718	    pub fn set_column_width(
719	        &mut self,
720	        window: WindowId,
721	        policy: WidthPolicy,
722	    ) -> Result<(), LayoutError> {
723	        policy.resolve(self.viewport.width)?;
724	        let index = self
725	            .column_index(window)
726	            .ok_or(LayoutError::UnknownWindow)?;
727	        self.check_strip_extent(
728	            self.viewport.width,
729	            self.gap,
730	            None,
731	            Some((index, policy)),
732	            0.0,
733	        )?;
734	        self.columns[index].width = policy;
735	        self.reveal_focus();
736	        Ok(())
737	    }
738	    pub fn set_column_mode(
739	        &mut self,
740	        window: WindowId,
741	        mode: ColumnMode,
742	    ) -> Result<(), LayoutError> {
743	        let index = self
744	            .column_index(window)
745	            .ok_or(LayoutError::UnknownWindow)?;
746	        self.columns[index].mode = mode;
747	        self.reveal_focus();
