750	    /// Move a member into another column, with no duplicate or orphan intermediate state.
751	    pub fn join_column(&mut self, window: WindowId, target: WindowId) -> Result<(), LayoutError> {
752	        let source = self
753	            .column_index(window)
754	            .ok_or(LayoutError::UnknownWindow)?;
755	        let dest = self
756	            .column_index(target)
757	            .ok_or(LayoutError::UnknownWindow)?;
758	        if self.is_minimized(window) || self.is_minimized(target) {
759	            return Err(LayoutError::MinimizedWindow);
760	        }
761	        if source == dest {
762	            return Ok(());
763	        }
764	        self.columns[source].windows.retain(|w| *w != window);
765	        if self.columns[source].active == window {
766	            self.columns[source].active = self.columns[source]
767	                .windows
768	                .iter()
769	                .copied()
770	                .find(|w| !self.minimized.contains(w))
771	                .or_else(|| self.columns[source].windows.first().copied())
772	                .unwrap_or(window);
773	        }
774	        self.columns[dest].windows.push(window);
775	        self.columns[dest].active = window;
776	        let dest_group = self.columns[dest].group;
777	        self.canvas.get_mut(&dest_group).unwrap().rect.width = self.canvas[&dest_group]
778	            .rect
779	            .width
780	            .max(self.members[&window].min.width);
781	        if self.columns[source].windows.is_empty() {
782	            self.canvas.remove(&self.columns[source].group);
783	            self.columns.remove(source);
784	        }
785	        self.focus_window(window)
786	    }
787	    pub fn resize_focused(&mut self, delta: f64) -> Result<(), LayoutError> {
788	        if !delta.is_finite() {
789	            return Err(LayoutError::InvalidGeometry);
790	        }
791	        let Some(window) = self.focus else {
792	            return Ok(());
793	        };
794	        if self.mode == LayoutMode::Canvas {
795	            let r = self.canvas[&self.group_for(window).unwrap()].rect;
796	            self.set_canvas_rect(
797	                window,
798	                Rect {
799	                    width: r.width + delta,
800	                    ..r
801	                },
802	            )?;
803	        } else {
804	            let i = self.column_index(window).unwrap();
805	            let width = self.columns[i].width.resolve(self.viewport.width)? + delta;
806	            self.set_column_width(window, WidthPolicy::Fixed(width))?;
807	        }
808	        self.reveal_focus();
809	        Ok(())
810	    }
811	    pub fn move_focused(&mut self, direction: Direction) -> Result<(), LayoutError> {
812	        let Some(window) = self.focus else {
813	            return Ok(());
814	        };
815	        if self.mode == LayoutMode::Canvas {
816	            let mut r = self.canvas[&self.group_for(window).unwrap()].rect;
817	            match direction {
818	                Direction::Left => r.x -= 32.0,
819	                Direction::Right => r.x += 32.0,
820	                Direction::Up => r.y -= 32.0,
821	                Direction::Down => r.y += 32.0,
822	            }
823	            self.set_canvas_rect(window, r)?;
824	        } else {
825	            let old_x = self
826	                .strip_placements()
827	                .into_iter()
828	                .find(|p| p.window == window)
829	                .unwrap()
830	                .rect
831	                .x;
832	            let i = self.column_index(window).unwrap();
833	            match direction {
834	                Direction::Left => {
835	                    if let Some(next) = (0..i)
836	                        .rev()
837	                        .find(|j| !self.is_minimized(self.columns[*j].active))
838	                    {
839	                        self.columns.swap(i, next);
840	                    }
841	                }
842	                Direction::Right => {
843	                    if let Some(next) = (i + 1..self.columns.len())
844	                        .find(|j| !self.is_minimized(self.columns[*j].active))
845	                    {
846	                        self.columns.swap(i, next);
847	                    }
848	                }
849	                Direction::Up | Direction::Down => {
850	                    let c = &mut self.columns[i];
851	                    let j = c.windows.iter().position(|w| *w == window).unwrap();
852	                    let next = if direction == Direction::Up {
